const processed = new Set();

async function handleOnce(consumer, eventId, work) {
  const key = `${consumer}:${eventId}`;
  if (processed.has(key)) return "duplicate";
  processed.add(key);
  try {
    await work();
  } catch (error) {
    processed.delete(key);
    throw error;
  }
  return "done";
}

let audit = 0;
let revenue = 0;
const log = [];
log.push(await handleOnce("audit", "evt-1", async () => { audit++; }));
log.push(await handleOnce("audit", "evt-1", async () => { audit++; }));
log.push(await handleOnce("analytics", "evt-1", async () => { revenue += 5; }));
try {
  await handleOnce("analytics", "evt-2", async () => { throw new Error("db down"); });
} catch (error) {
  log.push(error.message);
}
log.push(await handleOnce("analytics", "evt-2", async () => { revenue += 7; }));
console.log(log.join(", "));
console.log(audit, revenue);

