function parseOrderCreated(payload) {
  const fail = (field) => {
    throw new TypeError(`order.created: invalid ${field}`);
  };
  if (typeof payload?.orderId !== "string" || !payload.orderId.startsWith("ORD-")) fail("orderId");
  if (typeof payload.email !== "string" || !payload.email.includes("@")) fail("email");
  if (!Number.isSafeInteger(payload.totalKobo) || payload.totalKobo <= 0) fail("totalKobo");
  return payload;
}

