import { createEventBus } from "@zudojs/events";
import type { EventBus } from "@zudojs/events";

interface Contract<P> {
  readonly type: string;
  parse(payload: unknown): P;
}

function subscribe<P>(bus: EventBus, contract: Contract<P>, handler: (payload: P) => void): void {
  bus.on(contract.type, (event) => handler(contract.parse(event.payload)));
}

const StockLow: Contract<{ sku: string; left: number }> = {
  type: "stock.low",
  parse(payload) {
    const p = payload as { sku?: unknown; left?: unknown };
    if (typeof p.sku !== "string" || typeof p.left !== "number") throw new TypeError("stock.low: invalid payload");
    return { sku: p.sku, left: p.left };
  },
};

const bus = createEventBus();
subscribe(bus, StockLow, (stock) => console.log(`reorder ${stock.sku}, ${stock.left} left`));
await bus.publishEvent({ type: "stock.low", payload: { sku: "RICE-50KG", left: 3 } });
const bad = await bus.publishEvent({ type: "stock.low", payload: { sku: "RICE-50KG" } });
console.log("failed:", bad.failed, (bad.errors[0]?.cause as Error | undefined)?.message);

