function revenueByDay(deliveries) {
  const seen = new Set();
  const totals = {};
  for (const delivery of deliveries) {
    if (seen.has(delivery.id)) continue;
    seen.add(delivery.id);
    totals[delivery.day] = (totals[delivery.day] ?? 0) + delivery.totalKobo;
  }
  return totals;
}

